CREATE TABLE edge (a int, b int);
INSERT INTO edge VALUES (1, 2), (2, 3), (3, 1), (3, 4), (4, 5);
WITH RECURSIVE g AS (SELECT 1 AS n UNION ALL SELECT n + 1 FROM g WHERE n < 3) SEARCH BREADTH FIRST BY n SET ord SELECT *, pg_typeof(ord) FROM g ORDER BY ord;
WITH RECURSIVE g AS (SELECT 1 AS n UNION ALL SELECT n + 1 FROM g WHERE n < 3) SEARCH DEPTH FIRST BY n SET ord SELECT *, pg_typeof(ord) FROM g ORDER BY ord;
WITH RECURSIVE w(a, b) AS (SELECT a, b FROM edge WHERE a = 1 UNION ALL SELECT e.a, e.b FROM edge e JOIN w ON e.a = w.b) CYCLE a SET is_cycle USING path SELECT *, pg_typeof(path) FROM w ORDER BY path;
WITH RECURSIVE w(a, b) AS (SELECT a, b FROM edge WHERE a = 1 UNION ALL SELECT e.a, e.b FROM edge e JOIN w ON e.a = w.b) SEARCH DEPTH FIRST BY a, b SET s CYCLE a SET c TO 'y' DEFAULT 'n' USING p SELECT * FROM w ORDER BY s;
WITH RECURSIVE w(a, b) AS (SELECT a, b FROM edge WHERE a = 1 UNION ALL SELECT e.a, e.b FROM edge e, w WHERE e.a = w.b) SEARCH BREADTH FIRST BY b SET s CYCLE b SET c USING p SELECT a, b, s, c FROM w ORDER BY s;
WITH RECURSIVE w(a, b) AS (SELECT a, b FROM edge WHERE a = 1 UNION SELECT e.a, e.b FROM edge e JOIN w x ON e.a = x.b) CYCLE a, b SET c TO 1 DEFAULT 0 USING p SELECT count(*), sum(c) FROM w;
WITH RECURSIVE w AS (SELECT a, b FROM edge WHERE a = 1 UNION ALL SELECT e.* FROM edge e JOIN w ON e.a = w.b) CYCLE a SET c USING p SELECT max(array_length(p, 1)) FROM w;
WITH RECURSIVE g AS (SELECT 1 AS n UNION ALL SELECT n + 1 FROM g WHERE n < 3) SEARCH DEPTH FIRST BY x SET ord SELECT * FROM g;
WITH RECURSIVE g AS (SELECT 1 AS n UNION ALL SELECT n + 1 FROM g WHERE n < 3) SEARCH DEPTH FIRST BY n, n SET o SELECT * FROM g;
WITH RECURSIVE g AS (SELECT 1 AS n UNION ALL SELECT n + 1 FROM g WHERE n < 3) CYCLE x SET c USING p SELECT * FROM g;
WITH RECURSIVE g AS (SELECT 1 AS n UNION ALL SELECT n + 1 FROM g WHERE n < 3) CYCLE n SET c USING c SELECT * FROM g;
WITH RECURSIVE g AS (SELECT 1 AS n UNION ALL SELECT n + 1 FROM g WHERE n < 3) SEARCH DEPTH FIRST BY n SET o CYCLE n SET o USING p SELECT * FROM g;
WITH RECURSIVE g AS (SELECT 1 AS n UNION ALL SELECT n + 1 FROM g WHERE n < 3) CYCLE n SET c TO 1 DEFAULT 'x' USING p SELECT * FROM g;
WITH g AS (SELECT 1 AS n) SEARCH DEPTH FIRST BY n SET o SELECT * FROM g;
DROP TABLE edge;
